<?php
declare(strict_types=1);
namespace FMonitor2\AssignmentOrderComposition;
final readonly class MariaDbOriginalStartQuery
{
 public function __construct(private MariaDbAssignmentOrderApplicationSql$sql){}
 public function readCurrent(int$o,int$n):array{if($o<1||$n<1)return['status'=>'not_found','value'=>null];try{$r=$this->rows($o,$n,true);return$r===[]?['status'=>'not_found','value'=>null]:['status'=>'found','value'=>$r[0]];}catch(\Throwable){return['status'=>'unavailable','value'=>null];}}
 public function readHistory(int$o,int$n):array{if($o<1||$n<1)return['status'=>'not_found','rows'=>[]];try{$r=$this->rows($o,$n,false);return['status'=>$r===[]?'not_found':'found','rows'=>$r];}catch(\Throwable){return['status'=>'unavailable','rows'=>[]];}}
 public function readRequest(string$requestId,int$caseId,int$orderId):array{if($caseId<1||$orderId<1||preg_match('/^[0-9a-f-]{36}$/D',$requestId)!==1)return['status'=>'not_found','value'=>null];try{$r=$this->sql->rows('SELECT document_date,appendix_start_date,external_document_number FROM '.$this->sql->table('fm2_assignment_order_original_starts').' WHERE request_id=? AND installation_case_id=? AND assignment_order_id=?',[$requestId,$caseId,$orderId]);return count($r)===1?['status'=>'found','value'=>$r[0]]:['status'=>'not_found','value'=>null];}catch(\Throwable){return['status'=>'unavailable','value'=>null];}}
 private function rows(int$o,int$n,bool$c):array{$s=$this->sql;$w=$c?' AND r.current_revision_id=v.revision_id':'';$r=$s->rows('SELECT v.request_id,v.revision_id,v.revision_number,r.current_revision_id,s.appendix_start_date,s.external_document_number,c.actual_start_date,a.original_revision_id applied_revision FROM '.$s->table('fm2_assignment_order_original_roots').' r JOIN '.$s->table('fm2_assignment_order_original_revisions').' v ON v.root_original_id=r.root_original_id LEFT JOIN '.$s->table('fm2_assignment_order_original_starts').' s ON s.request_id=v.request_id JOIN '.$s->table('fm2_installation_cases').' c ON c.id=r.installation_case_id LEFT JOIN '.$s->table('fm2_assignment_order_applications').' a ON a.installation_case_id=c.id AND a.application_sequence=(SELECT MAX(x.application_sequence) FROM '.$s->table('fm2_assignment_order_applications').' x WHERE x.installation_case_id=c.id) WHERE c.legacy_installation_object_id=? AND r.assignment_order_id=?'.$w.' ORDER BY v.revision_number '.($c?'DESC':'ASC'),[$o,$n]);return array_map(static fn(array$x):array=>['requestId'=>$x['request_id'],'revisionId'=>$x['revision_id'],'revisionNumber'=>(int)$x['revision_number'],'appendixStartDate'=>$x['appendix_start_date'],'externalDocumentNumber'=>$x['external_document_number'],'openingComplete'=>$x['actual_start_date']!==null,'pending'=>$x['current_revision_id']===$x['revision_id']&&$x['applied_revision']!==$x['revision_id']],$r);}
}
